package httpkit

import (
	"errors"
	"net/http"

	ycerrors "github.com/slaghuis/yc-platform/libs/yc-errors"
)

// Error handlers for servers generated by oapi-codegen (api-conventions.md
// §2). Wire them as:
//
//	strict := api.NewStrictHandlerWithOptions(h, nil, api.StrictHTTPServerOptions{
//		RequestErrorHandlerFunc:  httpkit.RequestError,
//		ResponseErrorHandlerFunc: httpkit.ResponseError,
//	})
//	api.HandlerWithOptions(strict, api.ChiServerOptions{
//		BaseRouter:       r,
//		ErrorHandlerFunc: httpkit.ParamError,
//	})

// ParamError reports a path, query or header parameter that failed to
// parse as validation_failed.
func ParamError(w http.ResponseWriter, r *http.Request, err error) {
	ycerrors.WriteError(w, r, ycerrors.Validation().Message(err.Error()).Wrap(err))
}

// RequestError reports a request body that failed to decode as
// validation_failed.
func RequestError(w http.ResponseWriter, r *http.Request, err error) {
	msg := "Invalid request body"
	if _, ok := errors.AsType[*http.MaxBytesError](err); ok {
		msg = "Request body too large"
	}
	ycerrors.WriteError(w, r, ycerrors.Validation().Message(msg).Wrap(err))
}

// ResponseError writes an error returned by a strict handler. yc-errors
// errors keep their status; anything else is a 500.
func ResponseError(w http.ResponseWriter, r *http.Request, err error) {
	ycerrors.WriteError(w, r, err)
}

// LimitBody caps request bodies at n bytes for handlers that decode
// without DecodeJSON, such as generated strict servers. Pass MaxBodyBytes
// for JSON APIs.
func LimitBody(n int64) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			if r.Body != nil {
				r.Body = http.MaxBytesReader(w, r.Body, n)
			}
			next.ServeHTTP(w, r)
		})
	}
}
